import java.text.Normalizer;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.function.Predicate;
import java.util.regex.Pattern;

/**
 * Narrows the customer list. A customer is shown only if it satisfies both parts.
 *
 * <p>The name is split on whitespace into terms, and every term must occur as a
 * substring of the customer's first name or of its last name. Matching ignores
 * case and accents, in both directions.
 *
 * @param name     the text typed into the name filter; blank matches every name
 * @param statuses the statuses to show; empty shows every status
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    /** A filter that matches every customer. */
    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());

    private static final Pattern WHITESPACE = Pattern.compile("[\\s\\p{Zs}]+");
    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");

    public CustomerFilter {
        statuses = Set.copyOf(statuses);
    }

    /** Returns a predicate for this filter. Build it once per query, not once per customer. */
    public Predicate<Customer> asPredicate() {
        List<String> terms = terms(name);
        return customer -> (statuses.isEmpty() || statuses.contains(customer.status()))
                && nameMatches(terms, customer);
    }

    private static boolean nameMatches(List<String> terms, Customer customer) {
        if (terms.isEmpty()) {
            return true;
        }
        String first = fold(customer.firstName());
        String last = fold(customer.lastName());
        return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
    }

    private static List<String> terms(String text) {
        return WHITESPACE.splitAsStream(fold(text))
                .filter(term -> !term.isEmpty())
                .toList();
    }

    /**
     * Lower-cases the text and strips its accents, so that {@code Mäkinen},
     * {@code MAKINEN} and {@code makinen} all fold to the same string. Letters that
     * do not decompose into a base letter and an accent are mapped by hand.
     */
    private static String fold(String text) {
        String decomposed = Normalizer.normalize(text.toLowerCase(Locale.ROOT), Normalizer.Form.NFD);
        return COMBINING_MARKS.matcher(decomposed).replaceAll("")
                .replace("ß", "ss")
                .replace("æ", "ae")
                .replace("œ", "oe")
                .replace("ø", "o")
                .replace("đ", "d")
                .replace("ð", "d")
                .replace("ł", "l")
                .replace("þ", "th");
    }
}
