import static com.example.customers.domain.CustomerStatus.ACTIVE;
import static com.example.customers.domain.CustomerStatus.CLOSED;
import static com.example.customers.domain.CustomerStatus.PENDING;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Set;

import org.junit.jupiter.api.Test;

class CustomerFilterTest {

    private static final Customer ADA = new Customer(1, "Ada", "Aaltonen", "ada@example.com", "Finland", ACTIVE);
    private static final Customer JARNO = new Customer(2, "Jarno", "Mäkinen", "jarno@example.com", "Finland", PENDING);
    private static final Customer JOSEPHINE = new Customer(3, "Joséphine", "Engberg", "jo@example.com", "Denmark", CLOSED);
    private static final Customer HASSAN = new Customer(4, "Hassan", "Virtanen", "hassan@example.com", "Estonia", PENDING);

    private static boolean matches(String name, Customer customer) {
        return new CustomerFilter(name, Set.of()).asPredicate().test(customer);
    }

    @Test
    void everyTermMustAppearInTheFirstOrTheLastName() {
        assertTrue(matches("ada aal", ADA));
        assertTrue(matches("aal ada", ADA));
        assertFalse(matches("ada virtanen", ADA));
        assertFalse(matches("ada zzz", ADA));
    }

    @Test
    void termsMayComeFromDifferentNames() {
        assertTrue(matches("hassan virtanen", HASSAN));
        assertTrue(matches("virtanen hassan", HASSAN));
    }

    @Test
    void aTermIsAnySubstringNotOnlyAWord() {
        assertTrue(matches("aalt", ADA));
        assertTrue(matches("tonen", ADA));
    }

    @Test
    void whitespaceIsNotSignificant() {
        assertTrue(matches("  ada   aal  ", ADA));
        assertTrue(matches("\tada aal", ADA));
    }

    @Test
    void blankNameMatchesEveryCustomer() {
        assertTrue(matches("", ADA));
        assertTrue(matches("   ", JARNO));
    }

    @Test
    void matchingIgnoresCaseAndAccentsInBothDirections() {
        assertTrue(matches("makinen", JARNO));
        assertTrue(matches("MAKINEN", JARNO));
        assertTrue(matches("mäkinen", JARNO));
        assertTrue(matches("MÄKINEN", JARNO));
        assertTrue(matches("josephine", JOSEPHINE));
        assertTrue(matches("Joséphine", JOSEPHINE));
        assertTrue(matches("JOSEPHINE", JOSEPHINE));
    }

    @Test
    void lettersWithoutADecompositionAreFolded() {
        Customer strasse = new Customer(5, "Straße", "Søren", "s@example.com", "Norway", ACTIVE);
        assertTrue(matches("strasse", strasse));
        assertTrue(matches("soren", strasse));
        assertTrue(matches("Søren", strasse));
    }

    @Test
    void anEmptyStatusSetShowsEveryStatus() {
        CustomerFilter noStatus = new CustomerFilter("", Set.of());
        assertTrue(noStatus.asPredicate().test(ADA));
        assertTrue(noStatus.asPredicate().test(JARNO));
        assertTrue(noStatus.asPredicate().test(JOSEPHINE));
    }

    @Test
    void aStatusSetShowsOnlyThoseStatuses() {
        CustomerFilter activeOrClosed = new CustomerFilter("", Set.of(ACTIVE, CLOSED));
        assertTrue(activeOrClosed.asPredicate().test(ADA));
        assertFalse(activeOrClosed.asPredicate().test(JARNO));
        assertTrue(activeOrClosed.asPredicate().test(JOSEPHINE));
    }

    @Test
    void bothPartsMustMatch() {
        CustomerFilter filter = new CustomerFilter("mäkinen", Set.of(CLOSED));
        assertFalse(filter.asPredicate().test(JARNO));
    }
}

