/**
 * Drives the running application in a real browser, to check what the browserless
 * {@link CustomerListViewTest} cannot see: the address bar, the history, and how
 * many queries typing costs.
 *
 * <p>This is an integration test, so it is named {@code *IT} and {@code mvn test}
 * skips it. Run it with {@code mvn -o test -Dtest=CustomerListBrowserIT}. It needs
 * the Chromium that Playwright has installed offline.
 */
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class CustomerListBrowserIT extends AbstractBasePlaywrightIT {

    @LocalServerPort
    private int port;

    @Autowired
    private QueryLog queryLog;

    @Override
    public String getUrl() {
        return "http://localhost:" + port;
    }

    @Test
    void typingFollowsTheListWithOneQueryAndDoesNotAddHistoryEntries() {
        openView("/");
        assertThat(firstRowLastName()).hasText("Aaltonen");
        queryLog.clear();
        int historyBefore = historyLength();

        nameField().pressSequentially("makinen", new Locator.PressSequentiallyOptions().setDelay(50));

        assertThat(page.getByText("Showing 15 of 500", new Page.GetByTextOptions().setExact(true)))
                .isVisible();
        assertThat(firstRowLastName()).hasText("Mäkinen");
        assertEquals(List.of(15), queryLog.countQueries(), "Typing a name must cost one count query");
