+    /** Reads the filter from the URL. Unknown status names are ignored. */
+    private static CustomerFilter filterFrom(QueryParameters parameters) {
+        String name = parameters.getSingleParameter(NAME_PARAMETER).orElse("");
+        Set<String> requested = Arrays.stream(parameters.getSingleParameter(STATUS_PARAMETER).orElse("").split(","))
+                .map(status -> status.strip().toUpperCase(Locale.ROOT))
+                .collect(Collectors.toSet());
+        Set<CustomerStatus> statuses = Arrays.stream(CustomerStatus.values())
+                .filter(status -> requested.contains(status.name()))
+                .collect(Collectors.toSet());
+        return new CustomerFilter(name, statuses);
+    }
+
+    private static CustomerFilter filterOf(Query<Customer, CustomerFilter> query) {
+        return query.getFilter().orElse(CustomerFilter.NONE);
