+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+
+/**
+ * Drives the running application in a real browser, to check what the browserless
+ * {@link CustomerListViewTest} cannot see: the address bar, the history, and how
+ * many queries typing costs.
+ *
+ * <p>This is an integration test, so it is named {@code *IT} and {@code mvn test}
+ * skips it. Run it with {@code mvn -o test -Dtest=CustomerListBrowserIT}. It uses
+ * the Chromium that Playwright has installed offline.
+ */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class CustomerListBrowserIT extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Autowired
+    private QueryLog queryLog;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port;
+    }
+
+    @Test
+    void typingFollowsTheListWithOneQueryAndAddsNoHistoryEntries() {
+        openView("/");
+        assertThat(summary("Showing 500 of 500")).isVisible();
+        queryLog.clear();
+        int historyBefore = historyLength();
+
+        nameField().pressSequentially("makinen", new Locator.PressSequentiallyOptions().setDelay(50));
+
+        assertThat(summary("Showing 15 of 500")).isVisible();
+        assertThat(cell("Jarno")).isVisible();
+        assertThat(cell("Ada")).hasCount(0);
+        assertEquals(1, queryLog.countQueries().size(), "Typing a name must cost one count query");
+        assertEquals(15, queryLog.countQueries().get(0));
+        queryLog.pageQueries().forEach(page -> assertTrue(page.rowsReturned() <= 15));
+        assertEquals(historyBefore, historyLength(), "Typing must not add history entries");
+        expectQuery("name=makinen");
+    }
+
+    @Test
+    void openingTheListCostsOneCountQueryAndOnePage() {
+        queryLog.clear();
+        openView("/");
+        assertThat(summary("Showing 500 of 500")).isVisible();
+
+        assertEquals(List.of(500), queryLog.countQueries());
+        assertEquals(1, queryLog.pageQueries().size());
+        assertTrue(queryLog.pageQueries().get(0).limit() <= CustomerRepository.MAX_PAGE_SIZE);
+    }
+
+    @Test
+    void loadingTheAddressAppliesTheFilterAndShowsIt() {
+        openView("/?name=vir&status=ACTIVE,CLOSED");
+
+        assertThat(nameField()).hasValue("vir");
+        assertThat(summary("Showing 10 of 500")).isVisible();
+        expectQuery("name=vir&status=ACTIVE,CLOSED");
+    }
+
+    @Test
+    void clearingAFilterRemovesItsParameterAndNoOthers() {
+        openView("/?name=vir&status=CLOSED");
+        assertThat(summary("Showing 5 of 500")).isVisible();
+
+        nameField().fill("");
+
+        assertThat(summary("Showing 166 of 500")).isVisible();
+        expectQuery("status=CLOSED");
+    }
+
+    @Test
+    void clearingEveryFilterLeavesABareAddress() {
+        openView("/?name=vir&status=CLOSED");
+        assertThat(summary("Showing 5 of 500")).isVisible();
+
+        nameField().fill("");
+        assertThat(summary("Showing 166 of 500")).isVisible();
+        statusField().click();
+        page.locator("vaadin-multi-select-combo-box-item", new Page.LocatorOptions().setHasText("CLOSED")).click();
+        page.keyboard().press("Escape");
+
+        assertThat(summary("Showing 500 of 500")).isVisible();
+        expectQuery(null);
+        assertEquals("/", query().getPath());
+    }
+
+    @Test
+    void selectingStatusesWritesThemInDeclarationOrder() {
+        openView("/");
+
+        statusField().click();
+        page.locator("vaadin-multi-select-combo-box-item", new Page.LocatorOptions().setHasText("CLOSED")).click();
+        page.locator("vaadin-multi-select-combo-box-item", new Page.LocatorOptions().setHasText("ACTIVE")).click();
+        page.keyboard().press("Escape");
+
+        assertThat(summary("Showing 333 of 500")).isVisible();
+        expectQuery("status=ACTIVE,CLOSED");
+    }
+
+    /** Opens the view and waits until Flow has started it. Each test waits for its own result. */
+    private void openView(String path) {
+        page.navigate(getUrl() + path);
+        assertThat(page.locator("h2")).hasText("Customers");
+    }
+
+    /**
+     * Waits until the address bar shows {@code expected} as its query. The URL is
+     * written by a script that runs just after the summary has been updated, so it
+     * must not be read straight away. A {@code null} means no query at all.
+     */
+    private void expectQuery(String expected) {
+        page.waitForURL(url -> expected == null
+                ? URI.create(url).getQuery() == null
+                : expected.equals(URI.create(url).getQuery()));
+        assertEquals(expected, query().getQuery());
+    }
+
+    private Locator summary(String text) {
+        return page.getByText(text, new Page.GetByTextOptions().setExact(true));
+    }
+
+    private Locator nameField() {
+        return page.locator("vaadin-text-field input");
+    }
+
+    private Locator statusField() {
+        return page.locator("vaadin-multi-select-combo-box input");
+    }
+
+    /** A grid cell showing exactly {@code text}. */
+    private Locator cell(String text) {
+        return page.getByText(text, new Page.GetByTextOptions().setExact(true)).first();
+    }
+
+    private int historyLength() {
+        return ((Number) page.evaluate("history.length")).intValue();
+    }
+
+    /** The address bar, as the browser reports it. */
+    private URI query() {
+        return URI.create(page.url());
+    }
+}
